import { logger } from "../services/logger/logger.js";
import { memo, useState, useEffect, useRef } from "react";
import * as subcategoryService from "../services/subcategoryService";

/**
 * CategoryNavigation Component
 * Premium marketplace-style horizontal category navigation navbar.
 * Inspired by Noon, Amazon, and Flipkart category navigation.
 */
function CategoryNavigationComponent({ categories = [], onSelect, selectedCategory }) {
  const [canScrollLeft, setCanScrollLeft] = useState(false);
  const [canScrollRight, setCanScrollRight] = useState(true);
  const [hoveredCategoryId, setHoveredCategoryId] = useState(null);
  const [subcategories, setSubcategories] = useState({});
  const [loadingSubcategories, setLoadingSubcategories] = useState(null);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [headerHeight, setHeaderHeight] = useState(140);
  const scrollContainerRef = useRef(null);
  const scrollTimeoutRef = useRef(null);
  const dropdownTimeoutRef = useRef(null);

  useEffect(() => {
    const updateLayout = () => {
      setIsMobile(window.innerWidth < 1024);
      const header = document.querySelector('.enterprise-header');
      if (header) {
        setHeaderHeight(header.offsetHeight);
      }
    };

    updateLayout();
    window.addEventListener('resize', updateLayout);
    
    const header = document.querySelector('.enterprise-header');
    let ro;
    if (header && window.ResizeObserver) {
      ro = new ResizeObserver(() => updateLayout());
      ro.observe(header);
    }
    
    return () => {
      window.removeEventListener('resize', updateLayout);
      if (ro) ro.disconnect();
    };
  }, []);

  // Check scroll position for arrow visibility
  const checkScroll = () => {
    if (scrollContainerRef.current) {
      const { scrollLeft, scrollWidth, clientWidth } = scrollContainerRef.current;
      setCanScrollLeft(scrollLeft > 0);
      setCanScrollRight(scrollLeft < scrollWidth - clientWidth - 10);
    }
  };

  useEffect(() => {
    checkScroll();
    window.addEventListener("resize", checkScroll);
    return () => window.removeEventListener("resize", checkScroll);
  }, [categories]);

  // Smooth horizontal scroll
  const scroll = (direction) => {
    if (scrollContainerRef.current) {
      const scrollAmount = 200;
      scrollContainerRef.current.scrollBy({
        left: direction === "left" ? -scrollAmount : scrollAmount,
        behavior: "smooth",
      });
      
      if (scrollTimeoutRef.current) {
        clearTimeout(scrollTimeoutRef.current);
      }
      scrollTimeoutRef.current = setTimeout(checkScroll, 400);
    }
  };

  const handleCategorySelect = (category) => {
    onSelect?.(category);
    setTimeout(checkScroll, 50);
  };

  // Lazy load subcategories on hover
  const handleCategoryHover = async (categoryId) => {
    setHoveredCategoryId(categoryId);
    
    if (dropdownTimeoutRef.current) {
      clearTimeout(dropdownTimeoutRef.current);
    }

    if (subcategories[categoryId]) return;

    try {
      setLoadingSubcategories(categoryId);
      const response = await subcategoryService.getSubcategoriesByCategory(categoryId);
      setSubcategories((prev) => ({
        ...prev,
        [categoryId]: response.data || [],
      }));
    } catch (error) {
      logger.error("Failed to load subcategories:", { error: error });
    } finally {
      setLoadingSubcategories(null);
    }
  };

  const handleHoverLeave = () => {
    dropdownTimeoutRef.current = setTimeout(() => {
      setHoveredCategoryId(null);
    }, 150);
  };

  const categoryList = Array.isArray(categories) ? categories : [];

  if (categoryList.length === 0) {
    return null;
  }

  return (
    <>
      <nav
        className="category-navigation-sticky sticky mt-0 z-30 bg-white text-black backdrop-blur-md will-change-none"
        style={{ height: "48px", top: `${headerHeight}px` }}
      >
        <div className="w-full px-2 lg:px-4 h-full flex items-center relative">
          {/* Left Arrow */}
          {canScrollLeft && (
            <button
              type="button"
              onClick={() => scroll("left")}
              className="hidden lg:flex absolute left-0 z-10 h-full w-12 items-center justify-center bg-gradient-to-r from-white/80 to-transparent transition-colors duration-200 flex-shrink-0"
              aria-label="Scroll categories left"
            >
              <ChevronLeft className="h-4 w-4 text-black" />
            </button>
          )}

          {/* Categories Container */}
          <div
            ref={scrollContainerRef}
            onScroll={checkScroll}
            className="flex-1 overflow-x-auto scrollbar-hide flex items-center justify-center bg-white"
            style={{ scrollBehavior: "smooth", msOverflowStyle: "none" }}
          >
            <div className="mx-auto inner-category-list flex h-full items-center justify-start lg:justify-center gap-1 whitespace-nowrap px-2 lg:px-12">
              {categoryList.map((category) => {
                const isSelected = selectedCategory?.id === category.id || selectedCategory?.slug === category.slug;
                
                return (
                  <div
                    key={category.id}
                    onMouseEnter={() => handleCategoryHover(category.id)}
                    onMouseLeave={handleHoverLeave}
                    className="relative group"
                  >
                    <button
                      type="button"
                      onClick={() => handleCategorySelect(category)}
                      className={`flex items-center gap-2 px-2 py-1.5 text-[11px] lg:px-3 lg:py-2 lg:text-sm font-medium transition-all duration-200 relative group/btn ${
                        isSelected
                          ? "text-black"
                          : "text-black/70 hover:text-red-600"
                      }`}
                    >
                      <span className="flex-shrink-0">{category.name}</span>

                      {isSelected && (
                        <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-brand-primary rounded-full" />
                      )}

                      {!isSelected && (
                        <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-brand-primary rounded-full transform scale-x-0 group-hover/btn:scale-x-100 transition-transform duration-300 origin-center" />
                      )}
                    </button>

                    {/* Dropdown Submenu */}
                    {hoveredCategoryId === category.id && (
                      <div
                        className="absolute top-full left-0 pt-0 z-50 animate-in fade-in duration-150"
                        onMouseEnter={() => {
                          if (dropdownTimeoutRef.current) {
                            clearTimeout(dropdownTimeoutRef.current);
                          }
                        }}
                        onMouseLeave={handleHoverLeave}
                      >
                        <div className="bg-white shadow-brandMd border border-brand-border rounded-b-lg min-w-[200px] overflow-hidden">
                          {loadingSubcategories === category.id ? (
                            <div className="px-4 py-6 text-center text-xs text-slate-500">
                              Loading...
                            </div>
                          ) : (subcategories[category.id] || []).length > 0 ? (
                            <div className="grid grid-cols-1 divide-y divide-slate-100 dark:divide-slate-800">
                              {(subcategories[category.id] || []).slice(0, 8).map((sub) => (
                                <button
                                  key={sub._id || sub.id}
                                  type="button"
                                  onClick={() => {
                                    onSelect?.(sub);
                                    setHoveredCategoryId(null);
                                  }}
                                  className="px-4 py-2 text-xs sm:text-sm text-left text-slate-700 hover:bg-red-50 hover:text-brand-primary transition-colors duration-150 font-medium"
                                >
                                  {sub.name}
                                </button>
                              ))}
                            </div>
                          ) : (
                            <div className="px-4 py-6 text-center text-xs text-slate-500">
                              No subcategories
                            </div>
                          )}
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>

          {/* Right Arrow */}
          {canScrollRight && (
            <button
              type="button"
              onClick={() => scroll("right")}
              className="hidden lg:flex absolute right-0 z-10 h-full w-12 items-center justify-center bg-gradient-to-l from-brand-secondary to-transparent transition-colors duration-200 flex-shrink-0"
              aria-label="Scroll categories right"
            >
              <ChevronRight className="h-4 w-4 text-white" />
            </button>
          )}
        </div>
      </nav>

      <style>{`
        .scrollbar-hide {
          -ms-overflow-style: none;
          scrollbar-width: none;
        }
        .scrollbar-hide::-webkit-scrollbar {
          display: none;
        }

        @keyframes fadeInScale {
          from {
            opacity: 0;
            transform: scale(0.95);
          }
          to {
            opacity: 1;
            transform: scale(1);
          }
        }

        .animate-in {
          animation: fadeInScale 200ms ease-out forwards;
        }

        .fade-in {
          animation: fadeInScale 200ms ease-out;
        }
      `}</style>
    </>
  );
}

export const CategoryNavigation = memo(CategoryNavigationComponent);

import { logger } from "../services/logger/logger.js";
import { memo } from "react";

function reportProductCardError(message, details = {}) {
  const payload = {
    component: "ProductCard",
    message,
    productId: details.productId || "",
    errorMessage: details.error?.message || String(details.error || ""),
    stack: details.error?.stack,
  };

  if (import.meta.env.DEV) {
    logger.error("frontend_error", { error: message, payload });
    return;
  }

  window.dispatchEvent(new CustomEvent("app:error", { detail: payload }));
}

function getProductBrand(product) {
  return product?.brand || product?.vendorName || product?.sellerName || product?.category || "Daya";
}

const PremiumProductCard = memo(function PremiumProductCard({ product, cardStyle = "DEFAULT", imageAspectClass = "aspect-square", onProductClick }) {
  return (
    <ProductCardInner
      product={product}
      cardStyle={cardStyle}
      imageAspectClass={imageAspectClass}
      onProductClick={onProductClick}
    />
  );
});

export { PremiumProductCard as ProductCard };

import { useCallback, useEffect, useMemo, useState } from "react";
import { requestInput } from "../services/notificationService";
import { useAuthStore } from "../context/authStore";
import { resolveApiAssetUrl } from "../utils/resolveUrl";
import * as reviewService from "../services/reviewService";

const sortOptions = [
  ["most_recent", "Most Recent"],
  ["most_helpful", "Most Helpful"],
  ["highest_rating", "Highest Rating"],
  ["lowest_rating", "Lowest Rating"],
  ["oldest", "Oldest"],
];

function getProductImage(product) {
  const image = product?.images?.[0] || product?.image || product?.thumbnail;
  return typeof image === "string" ? image : image?.url || image?.secureUrl || "";
}

function getProductPrice(product) {
  return product?.salePrice ?? product?.pricing?.salePrice ?? product?.price ?? product?.pricing?.price ?? null;
}

function formatReviewDate(value) {
  if (!value) return "Recently";
  try {
    return new Intl.DateTimeFormat("en-IN", { day: "numeric", month: "short" }).format(new Date(value));
  } catch {
    return "Recently";
  }
}

export function ProductReviewsSection({ productId, product = null }) {
  const isAuthenticated = useAuthStore((state) => state.isAuthenticated);
  const user = useAuthStore((state) => state.user);
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [filter, setFilter] = useState({ sortBy: "most_recent" });
  const [form, setForm] = useState({ rating: 5, title: "", review: "", wouldRecommend: "" });
  const [media, setMedia] = useState([]);
  const [submitting, setSubmitting] = useState(false);

  const summary = data?.summary || {};
  const reviews = data?.reviews || [];
  const distribution = summary.ratingDistribution || {};

  const params = useMemo(
    () => Object.fromEntries(Object.entries(filter).filter(([, value]) => value !== "" && value !== false)),
    [filter]
  );

  const load = useCallback(async () => {
    if (!productId) return;
    setLoading(true);
    try {
      const response = await reviewService.getProductReviews(productId, params);
      setData(response.data);
      setError("");
    } catch (err) {
      setError(err?.response?.data?.message || "Failed to load reviews.");
    } finally {
      setLoading(false);
    }
  }, [params, productId]);

  useEffect(() => {
    void load();
  }, [load]);

  async function handleSubmit(event) {
    event.preventDefault();
    setSubmitting(true);
    setError("");
    try {
      await reviewService.submitReview({ ...form, productId }, media);
      setForm({ rating: 5, title: "", review: "", wouldRecommend: "" });
      setMedia([]);
      await load();
    } catch (err) {
      setError(err?.response?.data?.message || "Unable to submit review.");
    } finally {
      setSubmitting(false);
    }
  }

  async function handleVote(reviewId, voteType) {
    try {
      await reviewService.voteReview(reviewId, voteType);
      await load();
    } catch (err) {
      setError(err?.response?.data?.message || "Unable to save vote.");
    }
  }

  async function handleReport(reviewId) {
    const reason = await requestInput({
      title: "Report review",
      message: "Use one of: spam, fake_review, abusive_content, wrong_information, harassment, other.",
      label: "Report reason",
    });
    if (!reason) return;
    try {
      await reviewService.reportReview(reviewId, { reason });
    } catch (err) {
      setError(err?.response?.data?.message || "Unable to report review.");
    }
  }

  return (
    <section className="rounded-[2rem] border border-slate-200 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900 sm:p-5">
      <div className="flex items-center justify-between gap-4">
        <h2 className="text-lg font-bold text-slate-950 dark:text-white">Customer Reviews</h2>
        <button type="button" onClick={() => setFilter({ sortBy: "most_recent" })} className="text-sm font-semibold text-slate-600 hover:text-slate-950 dark:text-slate-300 dark:hover:text-white">
          View all reviews
        </button>
      </div>

      <div className="mt-4 flex gap-3 overflow-x-auto pb-2">
        <div className="min-h-[250px] w-[260px] shrink-0 rounded-xl border border-slate-200 bg-white p-4 dark:border-slate-800 dark:bg-slate-900">
          <div className="text-4xl font-semibold tracking-tight text-slate-950 dark:text-white">{Number(summary.averageRating || 0).toFixed(1)}</div>
          <div className="mt-2">
            <RatingStars value={summary.averageRating || 0} large />
          </div>
          <div className="mt-2 text-xs text-slate-500">Based on {(summary.totalReviews || summary.totalRatings || 0).toLocaleString()} reviews</div>
          <div className="mt-4 grid gap-2 text-xs">
            {[5, 4, 3, 2, 1].map((rating) => (
              <div key={rating} className="grid grid-cols-[1.5rem_minmax(0,1fr)_2.75rem] items-center gap-2">
                <span className="font-medium text-slate-700 dark:text-slate-200">{rating}</span>
                <div className="h-2 overflow-hidden rounded-full bg-slate-100 dark:bg-slate-800">
                  <div className="h-full rounded-full bg-amber-500" style={{ width: `${distribution[rating]?.percent || 0}%` }} />
                </div>
                <span className="text-right text-slate-500">{distribution[rating]?.count || 0}</span>
              </div>
            ))}
          </div>
        </div>

        {loading ? (
          <div className="flex min-h-[250px] min-w-[300px] items-center justify-center rounded-xl border border-slate-200 text-sm text-slate-500 dark:border-slate-800">
            Loading reviews...
          </div>
        ) : reviews.length ? (
          reviews.map((review) => (
            <HorizontalReviewCard key={review._id} review={review} product={product} onVote={handleVote} onReport={handleReport} />
          ))
        ) : (
          <EmptyReviewState />
        )}
      </div>

      {summary.media?.length ? (
        <div className="mt-4 flex gap-3 overflow-x-auto pb-1">
          {summary.media.map((item, index) => (
            <a key={`${item.url}-${index}`} href={resolveApiAssetUrl(item.url)} target="_blank" rel="noreferrer" className="h-20 w-20 shrink-0 overflow-hidden rounded-xl border border-slate-200 bg-slate-50 dark:border-slate-800">
              {item.mimeType?.startsWith("video") ? (
                <div className="flex h-full items-center justify-center text-slate-500"><Video size={22} /></div>
              ) : (
                <img src={resolveApiAssetUrl(item.url)} alt="Review media" className="h-full w-full object-cover" loading="lazy" />
              )}
            </a>
          ))}
        </div>
      ) : null}

      <div className="mt-5 flex flex-wrap items-center gap-2">
        {[["", "All Reviews"], [5, "5 Star"], [4, "4 Star"], [3, "3 Star"], [2, "2 Star"], [1, "1 Star"]].map(([value, label]) => (
          <button key={label} type="button" onClick={() => setFilter((next) => ({ ...next, rating: value }))} className={`rounded-full px-3 py-1.5 text-xs font-semibold ${String(filter.rating || "") === String(value) ? "bg-slate-950 text-white dark:bg-white dark:text-slate-950" : "bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-300"}`}>
            {label}
          </button>
        ))}
        <button type="button" onClick={() => setFilter((next) => ({ ...next, verifiedPurchase: next.verifiedPurchase ? "" : "true" }))} className="rounded-full bg-slate-100 px-3 py-1.5 text-xs font-semibold text-slate-600 dark:bg-slate-800 dark:text-slate-300">Verified Purchase</button>
        <button type="button" onClick={() => setFilter((next) => ({ ...next, withPhotos: next.withPhotos ? "" : "true" }))} className="inline-flex items-center gap-1 rounded-full bg-slate-100 px-3 py-1.5 text-xs font-semibold text-slate-600 dark:bg-slate-800 dark:text-slate-300"><ImageIcon size={14} /> Photos</button>
        <button type="button" onClick={() => setFilter((next) => ({ ...next, withVideos: next.withVideos ? "" : "true" }))} className="inline-flex items-center gap-1 rounded-full bg-slate-100 px-3 py-1.5 text-xs font-semibold text-slate-600 dark:bg-slate-800 dark:text-slate-300"><Video size={14} /> Videos</button>
        <select value={filter.sortBy} onChange={(event) => setFilter((next) => ({ ...next, sortBy: event.target.value }))} className="rounded-full border border-slate-200 bg-white px-3 py-1.5 text-xs font-semibold text-slate-700 dark:border-slate-700 dark:bg-slate-950 dark:text-slate-200">
          {sortOptions.map(([value, label]) => <option key={value} value={value}>{label}</option>)}
        </select>
      </div>

      {error ? <div className="mt-4 rounded-xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700">{error}</div> : null}

      {isAuthenticated && user?.role === "user" ? (
        <form onSubmit={handleSubmit} className="mt-6 grid gap-4 rounded-2xl bg-slate-50 p-4 dark:bg-slate-950">
          <div className="flex flex-wrap items-center gap-3">
            <label className="text-sm font-semibold text-slate-900 dark:text-white">Overall Rating</label>
            <div className="rounded-xl border border-slate-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-900">
              <RatingStars value={form.rating} onChange={(rating) => setForm((next) => ({ ...next, rating }))} large />
            </div>
          </div>
          <input value={form.title} onChange={(event) => setForm((next) => ({ ...next, title: event.target.value }))} maxLength={160} placeholder="Review title" className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm dark:border-slate-700 dark:bg-slate-900" />
          <textarea value={form.review} onChange={(event) => setForm((next) => ({ ...next, review: event.target.value }))} maxLength={2000} rows={4} placeholder="Review description" className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm dark:border-slate-700 dark:bg-slate-900" />
          <div className="flex flex-wrap items-center gap-3">
            <select value={form.wouldRecommend} onChange={(event) => setForm((next) => ({ ...next, wouldRecommend: event.target.value }))} className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-900">
              <option value="">Would recommend?</option>
              <option value="yes">Yes</option>
              <option value="no">No</option>
            </select>
            <input type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm,video/quicktime" multiple onChange={(event) => setMedia(Array.from(event.target.files || []).slice(0, 11))} className="text-sm text-slate-600 dark:text-slate-300" />
            <button type="submit" disabled={submitting} className="rounded-xl bg-[color:var(--commerce-accent)] px-4 py-2 text-sm font-semibold text-white disabled:opacity-60">
              {submitting ? "Submitting..." : "Submit Review"}
            </button>
          </div>
        </form>
      ) : null}
    </section>
  );
}

import { memo, useMemo } from "react";
import { resolveApiAssetUrl } from "../../utils/resolveUrl";

const DEFAULT_CANVAS_WIDTH = {
  desktop: 1440,
  tablet: 768,
  mobile: 375,
};

const DEVICE_COLUMNS = {
  desktop: 12,
  tablet: 6,
  mobile: 1,
};

const BANNER_HEIGHT_SCALE = 0.85;
const DEFAULT_BANNER_HEIGHT = 800;

export const DynamicHomepageRenderer = memo(function DynamicHomepageRenderer({
  rows = [],
  containers = [],
  loading = false,
  bareContainers = false,
  bareOuterLayout = false,
  bareCarouselShell = false,
  device = "desktop",
  canvasWidth,
  renderContext: externalRenderContext = {},
  insertAfterFeaturedProducts = null,
}) {
  const renderContext = useMemo(
    () => ({
      ...(externalRenderContext || {}),
      device,
      canvasWidth: resolveCanvasWidth(canvasWidth, device),
    }),
    [canvasWidth, device, externalRenderContext]
  );

  const resolvedRows = useMemo(() => {
    if (Array.isArray(rows) && rows.length) {
      return rows;
    }
    return buildRowsFromContainers(containers, renderContext.canvasWidth);
  }, [containers, rows, renderContext.canvasWidth]);

  const rowContent = useMemo(() => {
    if (!Array.isArray(resolvedRows) || !resolvedRows.length) {
      return { nodes: [], showFallback: false };
    }

    let featuredSlotInserted = false;
    let heroBannerRowSeen = false;
    const nodes = [];

    resolvedRows.forEach((row) => {
      const isHeroBannerRow = !heroBannerRowSeen && rowHasBanner(row);
      if (isHeroBannerRow) heroBannerRowSeen = true;

      nodes.push(
        <DynamicHomepageRow
          key={row.id || row.order}
          row={row}
          bareContainers={bareContainers}
          bareOuterLayout={bareOuterLayout}
          bareCarouselShell={bareCarouselShell}
          renderContext={renderContext}
          isHeroBannerRow={isHeroBannerRow}
        />
      );

      if (!featuredSlotInserted && insertAfterFeaturedProducts && rowHasFeaturedProducts(row)) {
        featuredSlotInserted = true;
        nodes.push(
          <Fragment key="after-featured-products">{insertAfterFeaturedProducts}</Fragment>
        );
      }
    });

    return {
      nodes,
      showFallback: !featuredSlotInserted && Boolean(insertAfterFeaturedProducts),
    };
  }, [
    bareCarouselShell,
    bareContainers,
    bareOuterLayout,
    insertAfterFeaturedProducts,
    renderContext,
    resolvedRows,
  ]);

  if (loading) {
    return (
      <>
        {Array.from({ length: 3 }).map((_, index) => (
          <SectionSkeleton key={index} />
        ))}
      </>
    );
  }

  if (Array.isArray(resolvedRows) && resolvedRows.length) {
    return (
      <div className="space-y-0">
        {rowContent.nodes}
        {rowContent.showFallback ? (
          <Fragment key="after-featured-products-fallback">{insertAfterFeaturedProducts}</Fragment>
        ) : null}
      </div>
    );
  }

  const containerNodes = [];
  let showFeaturedFallback = Boolean(insertAfterFeaturedProducts);
  containers.forEach((container, index) => {
    containerNodes.push(
      <DynamicHomepageSection
        key={container.instanceId || container._id}
        container={container}
        bareContainers={bareContainers}
        bareOuterLayout={bareOuterLayout}
        bareCarouselShell={bareCarouselShell}
        renderContext={renderContext}
      />
    );

    if (insertAfterFeaturedProducts && container.containerType === "FEATURED_PRODUCTS") {
      containerNodes.push(<Fragment key={`after-featured-${index}`}>{insertAfterFeaturedProducts}</Fragment>);
      showFeaturedFallback = false;
    }
  });

  if (showFeaturedFallback && insertAfterFeaturedProducts) {
    containerNodes.push(<Fragment key="after-featured-products-fallback">{insertAfterFeaturedProducts}</Fragment>);
  }

  return containerNodes;
});

function rowHasFeaturedProducts(row = {}) {
  return (row.columns || []).some((column) =>
    (column.containers || []).some((container) => container.containerType === "FEATURED_PRODUCTS")
  );
}

function rowHasBanner(row = {}) {
  return (row.columns || []).some((column) =>
    (column.containers || []).some((container) => container.containerType === "BANNER")
  );
}

function isManagedBannerContainer(container) {
  const config = container?.config || {};
  return Boolean(config.useManagedBanners || config.homepageBannerId || config.homepageBannerContainerId);
}

function getHeroBannerShellClass() {
  return "hero-banner-shell";
}

function flattenRowContainers(row = {}) {
  return (row.columns || []).flatMap((column) => column.containers || []);
}

function resolveRowBackdropUrl(row) {
  const containers = (row?.columns || [])
    .flatMap((column) => column?.containers || [])
    .filter(Boolean);
  const source =
    containers.find(
      (container) => ["BANNER", "SLIDER"].includes(container?.containerType) && !isManagedBannerContainer(container)
    ) ||
    containers.find(
      (container) =>
        !isManagedBannerContainer(container) && resolveContainerBackgroundMedia(resolveContainerLayout(container))
    );

  if (!source) return "";

  const config = source.config || {};
  const firstMedia = Array.isArray(config.bannerMedia) ? config.bannerMedia.find((item) => item?.url) : null;
  const raw =
    firstMedia?.url ||
    config.bannerImage ||
    config.bannerVideo ||
    config.slides?.find?.((slide) => slide?.image || slide?.url)?.image ||
    config.slides?.find?.((slide) => slide?.image || slide?.url)?.url ||
    resolveContainerBackgroundMedia(resolveContainerLayout(source));

  return raw ? resolveApiAssetUrl(raw) : "";
}

function resolveContainerVisibilityClasses(container) {
  const desktopVisible = container?.visibility?.desktop ?? container?.desktopVisible ?? true;
  const tabletVisible = container?.visibility?.tablet ?? container?.tabletVisible ?? true;
  const mobileVisible = container?.visibility?.mobile ?? container?.mobileVisible ?? true;

  if (!desktopVisible && !tabletVisible && !mobileVisible) {
    return "hidden";
  }

  if (desktopVisible && tabletVisible && mobileVisible) {
    return "";
  }

  const classes = [];
  classes.push(mobileVisible ? "block" : "hidden");
  classes.push(tabletVisible ? "md:block" : "md:hidden");
  classes.push(desktopVisible ? "lg:block" : "lg:hidden");

  return classes.join(" ");
}

function resolveContainerThemeStyles(themeValue) {
  const theme = String(themeValue || "default").trim().toLowerCase();
  switch (theme) {
    case "light":
      return { background: "#ffffff", color: "#0f172a" };
    case "dark":
      return { background: "#0f172a", color: "#f8fafc" };
    case "premium":
      return { background: "linear-gradient(135deg, #fef3c7, #fb923c)", color: "#3f2305" };
    case "luxury":
      return { background: "linear-gradient(135deg, #111827, #4b5563)", color: "#f8fafc" };
    case "modern":
      return { background: "linear-gradient(135deg, #dbeafe, #bfdbfe)", color: "#0f172a" };
    case "festival":
      return { background: "linear-gradient(135deg, #f97316, #ec4899)", color: "#fff7ed" };
    case "minimal":
      return { background: "#f8fafc", color: "#0f172a" };
    case "brand":
    case "default":
    default:
      return { background: "#ffffff", color: "#0f172a" };
  }
}

function resolveContainerDimensionStyle(layout, renderContext, options = {}) {
  const width = resolveConfiguredWidth(layout, renderContext.canvasWidth);
  const height = resolveConfiguredHeight(layout, {
    ...options,
    useViewportHeroHeight: options.containerType === "BANNER" && options.heroBannerLayout,
  });
  const exactSize = resolveResponsiveSize(width, height, renderContext);
  const styles = {};
  const applyHeight = (value) => {
    if (!value) return;
    if (options.contentSized) {
      styles.minHeight = `${value}px`;
    } else {
      styles.height = `${value}px`;
    }
  };

  if (options.inline) {
    styles.width = "100%";
    if (exactSize.height) {
      applyHeight(exactSize.height);
    } else if (!options.contentSized && height && width) {
      styles.aspectRatio = `${width} / ${height}`;
    }
  } else if (exactSize.width) {
    styles.width = `${exactSize.width}px`;
    if (exactSize.height) {
      applyHeight(exactSize.height);
    } else if (!options.contentSized && height && width) {
      styles.aspectRatio = `${width} / ${height}`;
    }
  } else {
    styles.width = "100%";
    if (exactSize.height) {
      applyHeight(exactSize.height);
    }
  }

  if (layout.alignment === "left") {
    styles.marginRight = "auto";
  } else if (layout.alignment === "right") {
    styles.marginLeft = "auto";
  } else {
    styles.marginInline = "auto";
  }

  return styles;
}

function parseLegacyMargin(value) {
  const raw = String(value || "").trim();
  if (!raw) return { top: undefined, right: undefined, bottom: undefined, left: undefined };
  const numbers = raw
    .split(/\s+/)
    .map((token) => Number(String(token).replace(/[^\d.-]/g, "")))
    .filter((value) => Number.isFinite(value));
  if (numbers.length === 0) return { top: undefined, right: undefined, bottom: undefined, left: undefined };
  if (numbers.length === 1) return { top: numbers[0], right: numbers[0], bottom: numbers[0], left: numbers[0] };
  if (numbers.length === 2) return { top: numbers[0], right: numbers[1], bottom: numbers[0], left: numbers[1] };
  if (numbers.length === 3) return { top: numbers[0], right: numbers[1], bottom: numbers[2], left: numbers[1] };
  return { top: numbers[0], right: numbers[1], bottom: numbers[2], left: numbers[3] };
}

function resolveContainerLayout(container) {
  const layout = container?.presentation?.layout || {};
  const legacyMargins = parseLegacyMargin(container?.presentation?.margin);
  const rawWidth = String(container?.presentation?.containerWidth || "").toLowerCase();
  const rawHeight = String(container?.presentation?.containerHeight || "").toLowerCase();
  const theme = String(layout.theme || container?.presentation?.containerTheme || "default").toLowerCase();

  return {
    width: pickFinite(layout.width),
    widthType: layout.widthType || (rawWidth === "full" ? "full" : rawWidth === "narrow" ? "narrow" : rawWidth === "medium" ? "medium" : rawWidth === "boxed" || rawWidth === "wide" || rawWidth === "content" ? "boxed" : "custom"),
    customWidth: Number(layout.customWidth || String(rawWidth).replace(/[^\d.-]/g, "") || 1400),
    height: pickFinite(layout.height),
    heightType: layout.heightType || (rawHeight === "auto" || !rawHeight ? "auto" : "custom"),
    customHeight: Number(layout.customHeight || String(rawHeight).replace(/[^\d.-]/g, "") || 450),
    alignment: layout.alignment || "center",
    positionX: Number(layout.positionX || String(container?.presentation?.containerOffsetX || "0").replace(/[^\d.-]/g, "") || 0),
    positionY: Number(layout.positionY || String(container?.presentation?.containerOffsetY || "0").replace(/[^\d.-]/g, "") || 0),
    padding: Number(layout.padding || String(container?.presentation?.padding || "24").replace(/[^\d.-]/g, "") || 24),
    marginTop: Number(layout.marginTop ?? legacyMargins.top ?? 16),
    marginBottom: Number(layout.marginBottom ?? legacyMargins.bottom ?? 16),
    marginLeft: Number(layout.marginLeft ?? legacyMargins.left ?? 0),
    marginRight: Number(layout.marginRight ?? legacyMargins.right ?? 0),
    backgroundType: layout.backgroundType || "solid",
    backgroundColor: layout.backgroundColor || container?.presentation?.backgroundColor || "#ffffff",
    gradientColor1: layout.gradientColor1 || "#fff7ed",
    gradientColor2: layout.gradientColor2 || "#fde68a",
    gradientDirection: layout.gradientDirection || "to right",
    backgroundImage: layout.backgroundImage || "",
    backgroundVideo: layout.backgroundVideo || "",
    theme,
    animation: layout.animation || "fadeUp",
  };
}

function pickFinite(value) {
  const next = Number(value);
  return Number.isFinite(next) && next > 0 ? next : null;
}

function resolveCanvasWidth(canvasWidth, device) {
  const next = Number(canvasWidth);
  if (Number.isFinite(next) && next > 0) {
    return next;
  }
  return DEFAULT_CANVAS_WIDTH[device] || DEFAULT_CANVAS_WIDTH.desktop;
}

function resolveConfiguredWidth(layout, canvasWidth) {
  if (pickFinite(layout.width)) {
    return pickFinite(layout.width);
  }
  if (pickFinite(layout.customWidth)) {
    return pickFinite(layout.customWidth);
  }
  switch (layout.widthType) {
    case "full":
      return canvasWidth || DEFAULT_CANVAS_WIDTH.desktop;
    case "narrow":
      return 900;
    case "medium":
      return 1200;
    case "boxed":
      return 1400;
    default:
      return null;
  }
}

function resolveConfiguredHeight(layout, options = {}) {
  const isBanner = options.containerType === "BANNER";

  if (options.isManagedBanner || options.useViewportHeroHeight) {
    return null;
  }

  const scale = isBanner ? BANNER_HEIGHT_SCALE : 1;
  const scaleHeight = (value) => (value ? Math.round(value * scale) : value);

  if (layout.heightType === "auto") {
    return isBanner ? scaleHeight(DEFAULT_BANNER_HEIGHT) : null;
  }
  if (pickFinite(layout.height)) {
    return scaleHeight(pickFinite(layout.height));
  }
  if (pickFinite(layout.customHeight)) {
    return scaleHeight(pickFinite(layout.customHeight));
  }
  switch (layout.heightType) {
    case "small":
      return scaleHeight(250);
    case "medium":
      return scaleHeight(450);
    case "large":
      return scaleHeight(650);
    case "extraLarge":
      return scaleHeight(850);
    default:
      return isBanner ? scaleHeight(DEFAULT_BANNER_HEIGHT) : null;
  }
}

function resolveResponsiveSize(width, height, renderContext) {
  if (!width) {
    return {
      width: null,
      height,
    };
  }

  if (renderContext.device === "desktop") {
    return { width, height };
  }

  const availableWidth = renderContext.canvasWidth || width;
  const nextWidth = Math.min(width, availableWidth);
  if (!height) {
    return { width: nextWidth, height: null };
  }
  return {
    width: nextWidth,
    height: Math.round((height * nextWidth) / width),
  };
}

function resolveColumnStyle(column, renderContext) {
  const maxColumns = DEVICE_COLUMNS[renderContext.device] || DEVICE_COLUMNS.desktop;
  const span = Math.min(Math.max(Number(column?.colSpan || column?.span || maxColumns), 1), maxColumns);
  return {
    gridColumn: `span ${span} / span ${span}`,
    minWidth: 0,
  };
}

function buildRowsFromContainers(containers, canvasWidth) {
  const list = Array.isArray(containers) ? containers.filter(Boolean) : [];
  if (!list.length) return [];

  const rows = [];
  let currentRow = [];
  let currentRowWidth = 0;

  list.forEach((container, index) => {
    const layout = resolveContainerLayout(container);
    const width = resolveConfiguredWidth(layout, canvasWidth) || canvasWidth;
    if (currentRow.length && currentRowWidth + width > canvasWidth) {
      rows.push({
        id: `row-${rows.length + 1}`,
        order: rows.length + 1,
        columns: currentRow,
      });
      currentRow = [];
      currentRowWidth = 0;
    }

    currentRow.push({
      id: container.instanceId || container._id || `column-${index + 1}`,
      order: currentRow.length + 1,
      widthPx: width,
      containers: [container],
    });
    currentRowWidth += width;
  });

  if (currentRow.length) {
    rows.push({
      id: `row-${rows.length + 1}`,
      order: rows.length + 1,
      columns: currentRow,
    });
  }

  return rows;
}

function resolveContainerBackground(layout, themeStyles) {
  if (layout.backgroundType === "solid") {
    return layout.backgroundColor || themeStyles.background;
  }
  if (layout.backgroundType === "gradient") {
    return `linear-gradient(${layout.gradientDirection}, ${layout.gradientColor1}, ${layout.gradientColor2})`;
  }
  return themeStyles.background;
}

function resolveContainerBackgroundMedia(layout) {
  const raw = layout.backgroundType === "video" ? layout.backgroundVideo : layout.backgroundImage;
  return raw ? resolveApiAssetUrl(raw) : "";
}

function renderContainer(container, options = {}) {
  switch (container.containerType) {
    case "BANNER":
      return (
        <BannerContainer
          container={container}
          heroBannerLayout={Boolean(options.heroBannerLayout || isManagedBannerContainer(container))}
          renderContext={options.renderContext}
          bareContainers={options.bareContainers}
          bareOuterLayout={options.bareOuterLayout}
          bareCarouselShell={options.bareCarouselShell}
        />
      );
    case "SLIDER":
      return <SliderContainer container={container} />;
    case "FEATURED_PRODUCTS":
      return <FeaturedProductsContainer container={container} renderContext={options.renderContext} />;
    case "MASONRY":
      return <MasonryContainer container={container} />;
    case "GRID":
    case "VIDEO_PRODUCTS":
    case "BRAND_SHOWCASE":
    case "RECENTLY_VIEWED":
    case "RECOMMENDED":
    case "TRENDING":
    case "NEW_ARRIVALS":
    case "TOP_RATED":
      return <GridFamilyContainer container={container} />;
    case "COMBO_DEALS":
      return <ComboDealsContainer container={container} />;
    case "CATEGORY_SHOWCASE":
      return <CategoryShowcaseContainer container={container} />;
    case "DEALS_STRIP":
      return <DealsStripContainer container={container} renderContext={options.renderContext} />;
    case "FLASH_SALE":
      return <FlashSaleContainer container={container} />;
    case "CAROUSEL":
    default:
      return <CarouselContainer container={container} bareContainers={options.bareContainers === true} bareOuterLayout={options.bareOuterLayout === true} bareCarouselShell={options.bareCarouselShell === true} />;
  }
}

function resolveFeaturedButtonStyles(config = {}) {
  const base = {
    backgroundColor: config.buttonColor || "#0f172a",
    color: config.buttonTextColor || "#ffffff",
    border: `1px solid ${config.buttonColor || "#0f172a"}`,
  };
  if (config.buttonStyle === "OUTLINE") {
    return { ...base, backgroundColor: "transparent", color: config.buttonColor || "#0f172a" };
  }
  if (config.buttonStyle === "GHOST") {
    return { ...base, backgroundColor: "transparent", borderColor: "transparent", color: config.buttonColor || "#0f172a" };
  }
  if (config.buttonStyle === "SECONDARY") {
    return { ...base, backgroundColor: "#f1f5f9", borderColor: "#e2e8f0", color: config.buttonColor || "#0f172a" };
  }
  return base;
}

function isContentSizedContainer(container) {
  return [
    "BRAND_SHOWCASE",
    "CAROUSEL",
    "CATEGORY_SHOWCASE",
    "COMBO_DEALS",
    "DEALS_STRIP",
    "FEATURED_PRODUCTS",
    "FLASH_SALE",
    "GRID",
    "MASONRY",
    "NEW_ARRIVALS",
    "RECENTLY_VIEWED",
    "RECOMMENDED",
    "TOP_RATED",
    "TRENDING",
    "VIDEO_PRODUCTS",
  ].includes(container?.containerType);
}

function resolveDealCountdown(endDate, now) {
  const end = new Date(endDate || now).getTime();
  const total = Number.isFinite(end) ? Math.max(0, end - now) : 0;
  const days = String(Math.floor(total / 86400000)).padStart(2, "0");
  const hours = String(Math.floor((total % 86400000) / 3600000)).padStart(2, "0");
  const minutes = String(Math.floor((total % 3600000) / 60000)).padStart(2, "0");
  const seconds = String(Math.floor((total % 60000) / 1000)).padStart(2, "0");
  return { total, days, hours, minutes, seconds };
}

function buildDealMarqueeText(promoItems = [], heading, config = {}) {
  return [
    ...promoItems.map((item) => item.label),
    heading,
    config.couponCode ? `Use ${config.couponCode}` : "Limited time offer",
  ]
    .filter(Boolean)
    .join(" / ");
}

function resolveDealWidth(width) {
  const value = String(width || "FULL").toUpperCase();
  if (value === "NARROW") return "mx-auto max-w-4xl";
  if (value === "BOXED") return "mx-auto max-w-7xl";
  return "";
}

function resolveDealBackground(config = {}) {
  const type = String(config.dealBackgroundType || "GRADIENT").toUpperCase();
  if (type === "SOLID") return { background: config.dealBackgroundColor || "#0f172a" };
  if (type === "IMAGE" || type === "VIDEO") return { background: config.dealBackgroundColor || "#0f172a" };
  return { background: `linear-gradient(120deg, ${config.dealGradientColor1 || "#e11d48"}, ${config.dealGradientColor2 || "#f97316"})` };
}

function resolveDealButtonStyle(config = {}) {
  const color = config.dealButtonColor || "#ffffff";
  const text = config.dealButtonTextColor || "#0f172a";
  if (config.dealButtonStyle === "OUTLINE") return { border: `1px solid ${color}`, color, background: "transparent" };
  if (config.dealButtonStyle === "GHOST") return { color, background: "rgba(255,255,255,0.12)" };
  if (config.dealButtonStyle === "GRADIENT") return { color: text, background: `linear-gradient(120deg, ${color}, ${config.dealButtonHoverColor || "#f8fafc"})` };
  return { color: text, background: color };
}

function resolveDealAlignment(alignment) {
  if (alignment === "CENTER") return "mx-auto text-center";
  if (alignment === "RIGHT") return "ml-auto text-right";
  return "";
}

function resolveDealAnimation(animation) {
  const value = String(animation || "FADE").toUpperCase();
  if (value === "PULSE") return "animate-pulse";
  if (value === "GLOW") return "ring-1 ring-white/20";
  return "";
}

function buildDealPromoItems(config = {}) {
  return [
    { label: config.offerText || "Flash sale", detail: config.dealPrimaryHeading || "Limited time deals", icon: <Zap className="h-5 w-5" /> },
    { label: config.couponCode ? `Use ${config.couponCode}` : "Extra savings", detail: config.dealSecondaryHeading || "Coupons and offers", icon: <Gift className="h-5 w-5" /> },
    { label: config.campaignTag || "Fast checkout", detail: config.disclaimer || "Selected products only", icon: <CreditCard className="h-5 w-5" /> },
  ];
}

function toDealLabel(value) {
  return String(value || "").replace(/_/g, " ");
}

function resolveEyebrow(type) {
  const map = {
    DEALS_STRIP: "Deals right now",
    RECENTLY_VIEWED: "Back in your orbit",
    RECOMMENDED: "Recommended for you",
    TRENDING: "Marketplace momentum",
    NEW_ARRIVALS: "Just landed",
    TOP_RATED: "Best reviewed",
    VIDEO_PRODUCTS: "Watch then shop",
    CATEGORY_SHOWCASE: "Category spotlight",
    BRAND_SHOWCASE: "Brand moment",
    COMBO_DEALS: "Bundle savings",
  };
  return map[type] || type.replace(/_/g, " ");
}

function resolveGridClass(type, config) {
  if (type === "LIST") {
    return "grid-cols-1";
  }
  const desktopColumns = Number(config.desktopColumns || 4);
  const columnClassMap = {
    1: "lg:grid-cols-1",
    2: "lg:grid-cols-2",
    3: "lg:grid-cols-3",
    4: "lg:grid-cols-4",
    5: "lg:grid-cols-5",
    6: "lg:grid-cols-6",
    7: "lg:grid-cols-7",
    8: "lg:grid-cols-8",
    9: "lg:grid-cols-9",
    10: "lg:grid-cols-10",
    11: "lg:grid-cols-11",
    12: "lg:grid-cols-12",
  };
  // if the requested desktopColumns is outside 1..12, fall back to 4
  return `sm:grid-cols-2 ${columnClassMap[desktopColumns] || "lg:grid-cols-4"}`;
}

function resolveMasonryColumns(config = {}) {
  const desktopColumns = Number(config.columnCount || config.desktopColumns || 4);
  const tabletColumns = Number(config.tabletColumns || 2);
  const mobileColumns = Number(config.mobileColumns || 1);
  const mobileMap = {
    1: "columns-1",
    2: "columns-2",
  };
  const tabletMap = {
    1: "sm:columns-1",
    2: "sm:columns-2",
    3: "sm:columns-3",
  };
  const desktopMap = {
    2: "lg:columns-2",
    3: "lg:columns-3",
    4: "lg:columns-4",
    5: "lg:columns-5",
    6: "lg:columns-6",
  };

  return [mobileMap[mobileColumns] || "columns-1", tabletMap[tabletColumns] || "sm:columns-2", desktopMap[desktopColumns] || "lg:columns-4"].join(" ");
}

function resolveMasonryImagePattern(cardHeights, imagePattern) {
  const pattern = String(imagePattern || cardHeights || "MIXED").toUpperCase();
  if (pattern === "AUTO" || pattern === "BALANCED") {
    return ["aspect-square", "aspect-square", "aspect-square", "aspect-square"];
  }
  if (pattern === "TALL") {
    return ["aspect-square", "aspect-square", "aspect-square", "aspect-square"];
  }
  if (pattern === "WIDE") {
    return ["aspect-square", "aspect-square", "aspect-square", "aspect-square"];
  }
  return ["aspect-square", "aspect-square", "aspect-square", "aspect-square"];
}

function resolveCategoryShowcaseItems(config = {}) {
  const items = Array.isArray(config.categoryCards) && config.categoryCards.length
    ? config.categoryCards
    : Array.isArray(config.categoryItems) && config.categoryItems.length
      ? config.categoryItems
      : config.categories || [];
  return (Array.isArray(items) ? items : [])
    .map((item) => {
      if (item && typeof item === "object") {
        return {
          _id: item._id || item.id || item.value || "",
          name: item.name || item.label || "",
          slug: item.slug || "",
          code: item.code || "",
          icon: item.icon || "",
          logo: item.logo || item.image || "",
          color: item.color || "",
          productCount: item.productCount || 0,
          description: item.description || "",
          linkUrl: item.linkUrl || item.url || "",
        };
      }
      return { _id: String(item), name: "", productCount: 0 };
    })
    .filter((item) => item.name);
}

function resolveCategoryShowcaseGrid(config = {}) {
  const columns = Number(config.categoryColumns || config.desktopColumns || 4);
  const columnClassMap = {
    2: "lg:grid-cols-2",
    3: "lg:grid-cols-3",
    4: "lg:grid-cols-4",
    5: "lg:grid-cols-5",
    6: "lg:grid-cols-6",
  };
  return `sm:grid-cols-2 ${columnClassMap[columns] || "lg:grid-cols-4"}`;
}

function resolveTextAlign(position) {
  switch (String(position || "LEFT").toUpperCase()) {
    case "CENTER":
      return "mx-auto text-center";
    case "RIGHT":
      return "ml-auto text-right";
    case "LEFT":
    default:
      return "text-left";
  }
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { resolveApiAssetUrl } from "../../utils/resolveUrl";
import { getHomepageBanners, trackHomepageBannerEvent } from "../../services/homepageBannerService";

const DEFAULT_SETTINGS = {
  maxCategoryCards: 6,
  autoplay: true,
  autoplayIntervalMs: 5000,
  transitionEffect: "fade",
  pauseOnHover: true,
  enableLoop: true,
  showArrows: true,
  showDots: true,
};

function getSessionId() {
  if (typeof window === "undefined") return "";
  const key = "homepage_banner_session";
  let sessionId = window.sessionStorage.getItem(key);
  if (!sessionId) {
    sessionId = `hb_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    window.sessionStorage.setItem(key, sessionId);
  }
  return sessionId;
}

function useIsMobile(breakpoint = 768) {
  const [isMobile, setIsMobile] = useState(() =>
    typeof window !== "undefined" ? window.matchMedia(`(max-width: ${breakpoint}px)`).matches : false
  );

  useEffect(() => {
    const media = window.matchMedia(`(max-width: ${breakpoint}px)`);
    const onChange = (event) => setIsMobile(event.matches);
    media.addEventListener("change", onChange);
    return () => media.removeEventListener("change", onChange);
  }, [breakpoint]);

  return isMobile;
}

function useInView(ref, rootMargin = "200px") {
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const node = ref.current;
    if (!node || typeof IntersectionObserver === "undefined") {
      setVisible(true);
      return undefined;
    }
    const observer = new IntersectionObserver(([entry]) => setVisible(entry.isIntersecting), { rootMargin });
    observer.observe(node);
    return () => observer.disconnect();
  }, [ref, rootMargin]);
  return visible;
}

function preloadBannerMedia(banners = [], startIndex = 0) {
  const targets = [startIndex, startIndex + 1].map((i) => banners[i % banners.length]).filter(Boolean);
  targets.forEach((banner) => {
    const urls = [banner.desktopMedia, banner.mobileMedia, banner.desktopImage, banner.mobileImage, banner.desktopPoster]
      .map((src) => resolveApiAssetUrl(src))
      .filter(Boolean);
    urls.forEach((url) => {
      if (/\.(mp4|webm|mov)(\?|$)/i.test(url)) return;
      const img = new Image();
      img.src = url;
    });
  });
}

function resolveBannerAsset(banner, isMobile) {
  const mediaType = banner?.mediaType || "image";
  const url = resolveApiAssetUrl(
    isMobile
      ? banner?.mobileMedia || banner?.mobileImage || banner?.desktopMedia || banner?.desktopImage
      : banner?.desktopMedia || banner?.desktopImage
  );
  const poster = resolveApiAssetUrl(
    isMobile
      ? banner?.mobilePoster || banner?.desktopPoster || banner?.mobileImage || banner?.desktopImage
      : banner?.desktopPoster || banner?.desktopImage
  );
  return { mediaType, url, poster };
}

function getSlideVariants(effect = "fade") {
  if (effect === "slide") {
    return {
      initial: { opacity: 0, x: 48 },
      animate: { opacity: 1, x: 0 },
      exit: { opacity: 0, x: -48 },
    };
  }
  if (effect === "zoom") {
    return {
      initial: { opacity: 0, scale: 1.08 },
      animate: { opacity: 1, scale: 1 },
      exit: { opacity: 0, scale: 0.96 },
    };
  }
  return {
    initial: { opacity: 0 },
    animate: { opacity: 1 },
    exit: { opacity: 0 },
  };
}

export function HomepageBannerSlider({
  banners = [],
  settings: settingsProp = {},
  className = "",
  previewMode = false,
  initialIndex = 0,
  embedded = false,
  headerSlot = null,
}) {
  const settings = useMemo(() => ({ ...DEFAULT_SETTINGS, ...settingsProp }), [settingsProp]);
  const [index, setIndex] = useState(initialIndex);
  const [hovered, setHovered] = useState(false);
  const trackedRef = useRef(new Set());
  const touchStartX = useRef(null);
  const containerRef = useRef(null);
  const scrollRef = useRef(null);
  const [currentCategoryIndex, setCurrentCategoryIndex] = useState(0);
  const sessionId = useMemo(() => getSessionId(), []);
  const isMobile = useIsMobile();
  const isDesktop = !isMobile;
  const inView = useInView(containerRef);

  const activeBanner = banners[index] || banners[0] || null;
  const maxCards = Number(settings.maxCategoryCards || 6);
  const autoplay = !previewMode && settings.autoplay !== false && banners.length > 1;
  const intervalMs = Math.max(3000, Number(settings.autoplayIntervalMs || 5000));
  const pauseOnHover = settings.pauseOnHover !== false;
  const showArrows = settings.showArrows !== false && banners.length > 1 && isDesktop;
  const showDots = settings.showDots !== false && banners.length > 1;
  const transitionEffect = settings.transitionEffect || "fade";
  const slideVariants = useMemo(() => getSlideVariants(transitionEffect), [transitionEffect]);

  const goTo = useCallback(
    (nextIndex) => {
      if (!banners.length) return;
      const last = banners.length - 1;
      if (settings.enableLoop === false) {
        setIndex(Math.min(Math.max(nextIndex, 0), last));
        return;
      }
      setIndex((nextIndex + banners.length) % banners.length);
    },
    [banners.length, settings.enableLoop]
  );

  useEffect(() => {
    setIndex((current) => (current >= banners.length ? 0 : current));
  }, [banners.length]);

  useEffect(() => {
    if (previewMode || !banners.length || !inView) return undefined;
    preloadBannerMedia(banners, index);
  }, [banners, index, inView, previewMode]);

  useEffect(() => {
    if (!autoplay || pauseOnHover && hovered) return undefined;
    const timer = window.setInterval(() => goTo(index + 1), intervalMs);
    return () => window.clearInterval(timer);
  }, [autoplay, goTo, hovered, index, intervalMs, pauseOnHover]);

  useEffect(() => {
    if (previewMode || !activeBanner?.id) return;
    const key = `${activeBanner.id}:view`;
    if (trackedRef.current.has(key)) return;
    trackedRef.current.add(key);
    trackHomepageBannerEvent(activeBanner.id, { eventType: "view", sessionId }).catch(() => { });
  }, [activeBanner?.id, previewMode, sessionId]);

  useEffect(() => {
    if (previewMode || banners.length <= 1) return undefined;
    function onKeyDown(event) {
      if (event.key === "ArrowLeft") {
        event.preventDefault();
        goTo(index - 1);
      }
      if (event.key === "ArrowRight") {
        event.preventDefault();
        goTo(index + 1);
      }
    }
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [banners.length, goTo, index, previewMode]);

  const handleBannerCta = () => {
    if (previewMode || !activeBanner?.id) return;
    trackHomepageBannerEvent(activeBanner.id, { eventType: "click", sessionId }).catch(() => { });
  };

  const handleCategoryClick = (card) => {
    if (previewMode || !activeBanner?.id) return;
    trackHomepageBannerEvent(activeBanner.id, {
      eventType: "category_click",
      categoryId: card.categoryId,
      sessionId,
    }).catch(() => { });
  };

  const handleTouchStart = (event) => {
    touchStartX.current = event.touches[0]?.clientX ?? null;
  };

  const handleTouchEnd = (event) => {
    if (touchStartX.current == null || banners.length <= 1) return;
    const delta = (event.changedTouches[0]?.clientX ?? touchStartX.current) - touchStartX.current;
    touchStartX.current = null;
    if (Math.abs(delta) < 40) return;
    goTo(delta > 0 ? index - 1 : index + 1);
  };

  if (!banners.length || !activeBanner) return null;

  const categories = Array.isArray(activeBanner.categories) ? activeBanner.categories.slice(0, maxCards) : [];
  const featuredText = activeBanner.featuredCollectionText || activeBanner.name;
  const showOverlay = Boolean(activeBanner.showOverlay) && Number(activeBanner.overlayOpacity || 0) > 0;
  const overlayOpacity = Math.min(1, Math.max(0, Number(activeBanner.overlayOpacity || 0)));
  const hoverReveal = Boolean(activeBanner.hoverModeEnabled) && isDesktop;
  const _revealContent = !hoverReveal || hovered || previewMode;

  const renderBannerCta = (className, overrideUrl) => {
    const targetUrl = overrideUrl || activeBanner.ctaUrl;
    if (!targetUrl) return null;
    const label = activeBanner.ctaText || "Shop now";
    if (previewMode) {
      return (
        <span className={className}>
          {label}
          <ArrowRight className="h-4 w-4" />
        </span>
      );
    }
    return (
      <Link to={targetUrl} onClick={handleBannerCta} className={className}>
        {label}
        <ArrowRight className="h-4 w-4" />
      </Link>
    );
  };

  const _textBlock = (
    <>
      <p className="text-[10px] font-black uppercase tracking-[0.32em] text-brand-primary sm:text-xs">
        {featuredText}
      </p>
      <h2
        className="mt-3 pt-8 max-w-[65ch] w-full text-center text-2xl font-black uppercase leading-tight tracking-[-0.03em] text-white sm:mt-4 sm:pt-10 sm:text-3xl md:text-4xl lg:text-5xl"
        style={{ textWrap: "balance", WebkitTextWrap: "balance", overflowWrap: "anywhere" }}
      >
        {activeBanner.title || activeBanner.name}
      </h2>
      {activeBanner.subtitle ? (
        <p className="mt-3 text-sm font-medium uppercase tracking-[0.16em] text-white/90 sm:mt-4 sm:text-base">
          {activeBanner.subtitle}
        </p>
      ) : null}
      {!isMobile && activeBanner.description ? (
        <p className="mt-3 max-w-2xl text-sm leading-7 text-white/80 sm:text-[15px]">
          {activeBanner.description}
        </p>
      ) : null}
    </>
  );

  return (
    <div
      className={`hero-banner relative w-full ${embedded ? "h-full" : "overflow-hidden"} ${className}`.trim()}
      ref={containerRef}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
    >
      <div
        className={`hero-banner-stack relative w-full ${embedded ? "h-full" : "min-h-[44rem] rounded-[1.5rem] border border-zinc-200 bg-white shadow-xl sm:min-h-[52rem] sm:rounded-[2rem]"}`}
        onTouchStart={handleTouchStart}
        onTouchEnd={handleTouchEnd}
        role="region"
        aria-roledescription="carousel"
        aria-label="Homepage banners"
      >
        <div className="hero-banner-overlay bg-zinc-900">
          <AnimatePresence mode="wait">
            <MotionDiv
              key={activeBanner.id || index}
              className="absolute inset-0"
              initial={slideVariants.initial}
              animate={slideVariants.animate}
              exit={slideVariants.exit}
              transition={{ duration: 0.35, ease: "easeOut" }}
            >
              <BannerMedia banner={activeBanner} isMobile={isMobile} isActive={inView} previewMode={previewMode} />
            </MotionDiv>
          </AnimatePresence>
          {showOverlay ? (
            <div className="absolute inset-0 bg-black" style={{ opacity: overlayOpacity }} aria-hidden="true" />
          ) : null}
        </div>

        <div className="hero-banner-foreground relative z-10 h-full">
          {headerSlot ? (
            <header className="hero-banner-header px-4 pt-3 sm:px-6 lg:px-8">{headerSlot}</header>
          ) : null}

          <div className="hero-banner-body h-full">
            <div className="hero-banner-content flex h-full flex-1 flex-col justify-center px-4 py-5 sm:px-6 sm:py-6 lg:items-end lg:px-8 lg:py-8">
              <div className="w-full max-w-[36rem] flex h-full flex-col justify-start gap-8 rounded-[1.6rem] bg-transparent p-0">
                <MotionDiv
                  key={`text-${activeBanner.id || index}`}
                  initial={{ opacity: 0, y: 12 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.35 }}
                  className="hidden md:flex min-h-[10rem] flex-col items-center justify-center gap-4 text-center transition-opacity duration-300"
                >
                  <div className="flex w-full flex-col items-center gap-4 px-4 text-center">
                    <div className="inline-flex items-center justify-center rounded-full border border-red-500 bg-transparent px-4 py-2">
                      <span className="text-sm font-bold uppercase tracking-wider text-red-500">Categories</span>
                    </div>
                    <p className="mx-auto w-full max-w-[42rem] text-xl font-semibold leading-tight text-white sm:text-2xl md:text-[1.6rem]">
                      Discover stylish, high-quality clothing crafted for everyday comfort
                    </p>
                  </div>
                </MotionDiv>

                {categories.length ? (
                  <div className="mt-4 hidden md:flex flex-row gap-2 md:gap-2 lg:gap-2 xl:gap-2 justify-center items-end flex-nowrap">
                    {categories.map((card, cardIndex) => (
                      <MotionDiv
                        key={card.id || card.categoryId}
                        initial={{ opacity: 0, y: 12 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: cardIndex * 0.05, duration: 0.28 }}
                        className="flex-none w-[50px] md:w-[50px] lg:w-[50px] xl:w-[150px]"
                      >
                        <BannerCategoryCard
                          card={card}
                          onSelect={handleCategoryClick}
                          previewMode={previewMode}
                        />
                      </MotionDiv>
                    ))}
                  </div>
                ) : null}
              </div>
            </div>
          </div>
          {isMobile && activeBanner.description ? (
            <div className="absolute inset-x-0 bottom-[3rem] z-20 mx-auto flex w-full max-w-[92%] flex-col items-center gap-3 rounded-3xl bg-transparent px-4 py-4 text-center text-white backdrop-blur-none md:hidden">
              <p className="text-sm leading-6 text-white/80">{activeBanner.description}</p>
              {renderBannerCta(
                "inline-flex items-center justify-center gap-2 rounded-full bg-brand-primary px-3 py-1.5 text-xs font-bold text-white transition hover:bg-brand-primaryHover",
                "/shop"
              )}
            </div>
          ) : isMobile ? (
            <div className="absolute inset-x-0 bottom-[3rem] z-20 mx-auto flex w-full max-w-[92%] items-center justify-center rounded-3xl bg-transparent px-4 py-4 text-center text-white backdrop-blur-none md:hidden">
              {renderBannerCta(
                "inline-flex items-center justify-center gap-2 rounded-full bg-brand-primary px-3 py-1.5 text-xs font-bold text-white transition hover:bg-brand-primaryHover",
                "/shop"
              )}
            </div>
          ) : null}
        </div>

        {showArrows ? (
          <>
            <button
              type="button"
              aria-label="Previous banner"
              onClick={() => goTo(index - 1)}
              className="absolute left-3 top-1/2 z-20 hidden -translate-y-1/2 items-center justify-center rounded-full bg-white/90 text-zinc-900 shadow-lg transition hover:bg-white sm:left-4 lg:inline-flex lg:h-10 lg:w-10"
            >
              <ChevronLeft className="h-5 w-5" />
            </button>
            <button
              type="button"
              aria-label="Next banner"
              onClick={() => goTo(index + 1)}
              className="absolute right-3 top-1/2 z-20 hidden -translate-y-1/2 items-center justify-center rounded-full bg-white/90 text-zinc-900 shadow-lg transition hover:bg-white sm:right-4 lg:inline-flex lg:h-10 lg:w-10"
            >
              <ChevronRight className="h-5 w-5" />
            </button>
          </>
        ) : null}

        {showDots ? (
          <div
            className="absolute bottom-3 left-1/2 z-20 flex -translate-x-1/2 gap-2 sm:bottom-4"
            role="tablist"
            aria-label="Banner slides"
          >
            {banners.map((banner, bannerIndex) => (
              <button
                key={banner.id || banner.slug || bannerIndex}
                type="button"
                role="tab"
                aria-label={`Show banner ${banner.name}`}
                aria-selected={bannerIndex === index}
                onClick={() => goTo(bannerIndex)}
                className={`h-2 rounded-full transition-all ${bannerIndex === index ? "w-7 bg-brand-primary" : "w-2 bg-white/70 hover:bg-white"
                  }`}
              />
            ))}
          </div>
        ) : null}
      </div>
      {categories.length ? (
        <div className="mt-4 px-4 pb-4 md:hidden">
          <div className="mb-6 flex flex-col items-center gap-3 text-center md:hidden">
            <div className="inline-flex items-center justify-center rounded-full border border-red-500 bg-transparent px-4 py-2">
              <span className="text-xs font-bold uppercase tracking-wider text-red-500 sm:text-sm">Categories</span>
            </div>
            <p className="mx-auto max-w-[42rem] text-sm font-semibold leading-6 text-white sm:text-base">
              Explore a wide range of stylish apparel, designed for comfort, quality, and everyday wear.
            </p>
          </div>
          <div
            ref={scrollRef}
            onScroll={() => {
              if (!scrollRef.current) return;
              const { scrollLeft, clientWidth } = scrollRef.current;
              const cardWidth = scrollRef.current.children[0]?.clientWidth || (clientWidth / 2);
              if (cardWidth > 0) {
                setCurrentCategoryIndex(Math.round(scrollLeft / cardWidth));
              }
            }}
            className="flex gap-4 overflow-x-auto scroll-smooth snap-x snap-mandatory scrollbar-hide pb-2"
            role="list"
            aria-label="Homepage category cards"
          >
            {categories.map((card, cardIndex) => (
              <MotionDiv
                key={card.id || card.categoryId}
                initial={{ opacity: 0, y: 12 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: cardIndex * 0.05, duration: 0.28 }}
                className="snap-start shrink-0 w-[calc((100%-1rem)/2)] min-w-[calc((100%-1rem)/2)]"
              >
                <BannerCategoryCard
                  card={card}
                  onSelect={handleCategoryClick}
                  previewMode={previewMode}
                />
              </MotionDiv>
            ))}
          </div>
          {categories.length > 2 && (
            <div className="mt-3 flex justify-center gap-1.5">
              {Array.from({ length: categories.length - 1 }).map((_, i) => (
                <button
                  key={i}
                  onClick={() => {
                    if (!scrollRef.current) return;
                    const cardWidth = scrollRef.current.children[0]?.clientWidth || (scrollRef.current.clientWidth / 2);
                    scrollRef.current.scrollTo({
                      left: i * cardWidth,
                      behavior: 'smooth'
                    });
                  }}
                  className={`h-1.5 rounded-full transition-all ${(currentCategoryIndex || 0) === i ? "w-4 bg-brand-primary" : "w-1.5 bg-zinc-300"
                    }`}
                  aria-label={`Go to category slide ${i + 1}`}
                />
              ))}
            </div>
          )}
        </div>
      ) : null}
    </div>
  );
}

export function useHomepageBanners() {
  const [data, setData] = useState({ container: null, settings: {}, banners: [] });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    async function load() {
      setLoading(true);
      try {
        const response = await getHomepageBanners();
        if (!cancelled) setData(response);
      } catch {
        if (!cancelled) setData({ container: null, settings: {}, banners: [] });
      } finally {
        if (!cancelled) setLoading(false);
      }
    }
    load();
    return () => {
      cancelled = true;
    };
  }, []);

  return { ...data, loading, hasManagedBanners: data.banners.length > 0 };
}

import { useEffect, useState, useCallback } from "react";
import { getStorefrontTestimonials } from "../../services/reviewService";

function getProductImage(product) {
  const image = product?.images?.[0] || product?.image || product?.thumbnail;
  return typeof image === "string" ? image : image?.url || image?.secureUrl || "";
}

function getProductPrice(product) {
  return (
    product?.salePrice ??
    product?.pricing?.salePrice ??
    product?.price ??
    product?.pricing?.price ??
    null
  );
}

function getCustomerInitial(name) {
  return (name || "U").charAt(0).toUpperCase();
}

export function HomepageTestimonials() {
  const [reviews, setReviews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [currentPage, setCurrentPage] = useState(0);
  const [cardsPerPage, setCardsPerPage] = useState(3);

  useEffect(() => {
    let cancelled = false;
    async function load() {
      try {
        const response = await getStorefrontTestimonials();
        if (!cancelled) {
          setReviews(response?.data || response || []);
        }
      } catch {
        // Silently fail — testimonials are optional
      } finally {
        if (!cancelled) setLoading(false);
      }
    }
    load();
    return () => { cancelled = true; };
  }, []);

  const [isMobile, setIsMobile] = useState(false);

  // Responsive cards per page
  useEffect(() => {
    function handleResize() {
      const w = window.innerWidth;
      if (w < 640) {
        setCardsPerPage(1);
        setIsMobile(true);
      } else if (w < 1024) {
        setCardsPerPage(2);
        setIsMobile(false);
      } else {
        setCardsPerPage(3);
        setIsMobile(false);
      }
    }
    handleResize();
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const totalPages = Math.ceil(reviews.length / cardsPerPage);

  // Reset page if out of bounds when cardsPerPage changes
  useEffect(() => {
    if (currentPage >= totalPages && totalPages > 0) {
      setCurrentPage(totalPages - 1);
    }
  }, [cardsPerPage, totalPages, currentPage]);

  const goToPage = useCallback((page) => {
    setCurrentPage(Math.max(0, Math.min(page, totalPages - 1)));
  }, [totalPages]);

  // Auto-rotate every 5 seconds (disable on mobile for native scroll)
  useEffect(() => {
    if (totalPages <= 1 || isMobile) return;
    const interval = setInterval(() => {
      setCurrentPage((prev) => (prev + 1) % totalPages);
    }, 5000);
    return () => clearInterval(interval);
  }, [totalPages, isMobile]);

  if (loading || reviews.length === 0) return null;

  const startIndex = currentPage * cardsPerPage;
  const visibleReviews = isMobile ? reviews : reviews.slice(startIndex, startIndex + cardsPerPage);

  return (
    <section className="testimonials-section" id="homepage-testimonials">
      <div className="testimonials-section__inner">
        {/* Header */}
        <div className="testimonials-section__header">
          <span className="testimonials-section__badge">TESTIMONIALS</span>
          <h2 className="testimonials-section__title">
            What Our Clients Say <span className="testimonials-section__emoji">👍</span>
          </h2>
        </div>

        {/* Cards grid */}
        <div
          className="testimonials-section__grid"
          style={{ "--cards-per-page": cardsPerPage }}
        >
          {visibleReviews.map((review) => (
            <TestimonialCard key={review._id} review={review} />
          ))}
        </div>

        {/* Dot pagination */}
        {!isMobile && totalPages > 1 ? (
          <div className="testimonials-section__dots">
            {Array.from({ length: totalPages }).map((_, i) => (
              <button
                key={i}
                type="button"
                aria-label={`Go to page ${i + 1}`}
                className={`testimonials-section__dot ${
                  i === currentPage ? "testimonials-section__dot--active" : ""
                }`}
                onClick={() => goToPage(i)}
              />
            ))}
          </div>
        ) : null}
      </div>
    </section>
  );
}

import { useState, useEffect, useRef } from "react";

const CONTAINER_CLASS = "relative z-10 mx-auto w-full max-w-[1600px] px-8";

export function ReelCarousel({
  items = [],
  loading = false,
  title,
  swipeEnabled = true,
  desktopItemsPerView = 4,
  tabletItemsPerView = 2,
}) {
  const [itemsPerView, setItemsPerView] = useState(4);
  const [isMobileScroll, setIsMobileScroll] = useState(false);
  const scrollRef = useRef(null);
  const [canScrollLeft, setCanScrollLeft] = useState(false);
  const [canScrollRight, setCanScrollRight] = useState(true);

  useEffect(() => {
    const handleResize = () => {
      const width = window.innerWidth;
      if (width < 768) {
        setIsMobileScroll(true);
        setItemsPerView(1);
      } else if (width < 1024) {
        setIsMobileScroll(false);
        setItemsPerView(tabletItemsPerView);
      } else {
        setIsMobileScroll(false);
        setItemsPerView(desktopItemsPerView);
      }
    };

    handleResize();
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, [desktopItemsPerView, tabletItemsPerView]);

  const checkScroll = () => {
    if (!scrollRef.current) return;
    const { scrollLeft, scrollWidth, clientWidth } = scrollRef.current;
    setCanScrollLeft(scrollLeft > 0);
    setCanScrollRight(Math.ceil(scrollLeft + clientWidth) < scrollWidth - 5);
  };

  useEffect(() => {
    checkScroll();
    window.addEventListener("resize", checkScroll);
    return () => window.removeEventListener("resize", checkScroll);
  }, [items]);

  const scrollByOne = (direction) => {
    if (!scrollRef.current) return;
    // item width (280) + gap (24) = 304
    const scrollAmount = 304 * direction;
    scrollRef.current.scrollBy({ left: scrollAmount, behavior: "smooth" });
  };

  if (loading) {
    return (
      <ReelsSectionShell title={title}>
        <div className="mx-auto flex max-w-[1192px] justify-center gap-6 overflow-hidden pb-2">
          {Array.from({ length: 4 }).map((_, index) => (
            <div key={index} className="w-[min(280px,100%)] shrink-0">
              <div className="h-[500px] animate-pulse overflow-hidden rounded-2xl bg-slate-100 shadow-[0_25px_60px_rgba(0,0,0,0.18)]" />
            </div>
          ))}
        </div>
      </ReelsSectionShell>
    );
  }

  if (!items.length) return null;

  const justifyClass = items.length <= itemsPerView ? "md:justify-center" : "md:justify-start";

  const flexClass = `scroll-smooth scrollbar-hide flex snap-x snap-mandatory justify-start gap-4 overflow-x-auto pb-2 md:gap-6 md:snap-none md:overflow-x-hidden ${justifyClass}`;

  const maxGroupWidth = !isMobileScroll ? itemsPerView * 280 + Math.max(0, itemsPerView - 1) * 24 + 128 : "100%";

  return (
    <ReelsSectionShell title={title}>
      <div 
        className="relative group mx-auto md:px-16"
        style={{ maxWidth: maxGroupWidth }}
      >
        {/* Navigation Buttons */}
        {!isMobileScroll && items.length > itemsPerView && (
          <>
            <button
              onClick={() => scrollByOne(-1)}
              disabled={!canScrollLeft}
              className="absolute left-0 top-1/2 z-20 flex h-12 w-12 -translate-y-1/2 items-center justify-center rounded-full bg-white text-gray-800 shadow-[0_4px_14px_rgba(0,0,0,0.1)] transition-all hover:scale-105 hover:bg-gray-50 disabled:opacity-50 disabled:hover:scale-100"
              aria-label="Previous page"
            >
              <ChevronLeft size={24} />
            </button>
            <button
              onClick={() => scrollByOne(1)}
